/* volets des chiffres */
function runFlaps(){$$('.ch[data-c]').forEach((el,k)=>{const fin=el.dataset.c;if(!/\d/.test(fin)){el.textContent=fin;return;}if(reduce){el.textContent=fin;return;}let n=0;const max=10+k*2;const iv=setInterval(()=>{n++;el.classList.remove('flip');void el.offsetWidth;el.classList.add('flip');el.textContent=n>=max?fin:String(Math.floor(Math.random()*10));if(n>=max)clearInterval(iv);},70);});}

/* lecture progressive de la citation */
function quoteFill(){const q=$('#quote');if(!q)return;const r=q.getBoundingClientRect(),vh=innerHeight;let p=(vh*.9-r.top)/(r.height+vh*.35);p=reduce?1:Math.max(0,Math.min(1,p));const ws=q.querySelectorAll('.w,.inl'),n=Math.round(p*ws.length);ws.forEach((w,i)=>w.classList.toggle('on',i<n));}

