function setStep(i){const t=T[lang];stepI=i;$$('#steps .st').forEach((s,k)=>{s.className='st'+(k<i?' done':k===i?' now':'');s.querySelector('.d').textContent=k<i?'✓':'0'+(k+1);});
 $('#tfill').style.width=(75*i/3)+'%';$('#status').textContent=t.status[i];
 $('#log').innerHTML='<i>'+BELL+'</i><span>'+t.logs[i]+'</span>';}
function startSteps(){if(reduce||stepTimer)return;stepTimer=setInterval(()=>setStep((stepI+1)%4),2600);}

const header=$('#header');
let scrollQueued=false;function updateScroll(){header.classList.toggle('solid',scrollY>10);quoteFill();scrollQueued=false;}
addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateScroll);}},{passive:true});
requestAnimationFrame(updateScroll);
addEventListener('pageshow',()=>{document.body.classList.add('ready');requestAnimationFrame(updateScroll);});
let io;
function observe(){
 if(!reduce&&'IntersectionObserver' in window){$$('.q,.flap').forEach((el,i)=>{el.classList.add('motion-reveal');el.style.setProperty('--motion-order',i%4);});}
 if(!('IntersectionObserver' in window)){$$('.rv').forEach(e=>e.classList.add('in'));return;}
 io=io||new IntersectionObserver(es=>es.forEach(en=>{if(!en.isIntersecting)return;en.target.classList.add('in','motion-in');
  if(en.target.id==='flaps'&&!flapsDone){flapsDone=true;runFlaps();}
  if(en.target.id==='dossier')startSteps();
  io.unobserve(en.target);}),{threshold:.08,rootMargin:'0px 0px -20px 0px'});
 $$('.rv:not(.in),.motion-reveal:not(.motion-in)').forEach(e=>io.observe(e));
}
