function legalPage(){
 const records=[[bi('Texte fondateur de l’Agence','النص المؤسس للوكالة'),bi('Organisation','التنظيم'),'organisation',bi('Création et cadre institutionnel de l’Agence.','الإنشاء والإطار المؤسسي للوكالة.')],[bi('Textes relatifs aux attributions','النصوص المتعلقة بالاختصاصات'),bi('Attributions','الاختصاصات'),'missions',bi('Définition des missions et du champ de compétence.','تحديد المهام ونطاق الاختصاص.')],[bi('Textes de procédure','النصوص الإجرائية'),bi('Procédures','الإجراءات'),'procedure',bi('Cadre de préparation et de traitement des dossiers.','إطار إعداد الملفات ومعالجتها.')]];
 const filters=[['all',bi('Tous les textes','جميع النصوص')],['organisation',bi('Organisation','التنظيم')],['missions',bi('Attributions','الاختصاصات')],['procedure',bi('Procédures','الإجراءات')]];
 return pageFrame('juridique',bi('Retrouver les textes de référence et leurs versions officielles.','العثور على النصوص المرجعية ونسخها الرسمية.'),'<div class="legal-page-heading"><div><span class="mini-label">'+bi('La bibliothèque juridique','المكتبة القانونية')+'</span><h2>'+bi('Le cadre de notre action.','الإطار المنظم لعملنا.')+'</h2></div><p>'+bi('Un classement simple pour identifier le texte utile à votre démarche.','تصنيف واضح لتحديد النص المفيد لإجراءك.')+'</p></div><div class="legal-discovery"><div class="legal-search">'+searchControl('legal-list',bi('Rechercher un texte, un thème…','البحث عن نص أو موضوع…'))+'</div><div class="legal-controls"><div class="filter-buttons" role="group" aria-label="'+bi('Catégories de textes','تصنيفات النصوص')+'">'+filters.map((r,i)=>'<button type="button" data-filter="'+r[0]+'" data-target="legal-list" aria-pressed="'+(i===0)+'">'+r[1]+'</button>').join('')+'</div><div class="layout-switch" role="group" aria-label="'+bi('Affichage des textes','طريقة عرض النصوص')+'"><button type="button" data-legal-layout="cards" aria-pressed="true">'+bi('Cartes','بطاقات')+'</button><button type="button" data-legal-layout="list" aria-pressed="false">'+bi('Liste','قائمة')+'</button></div></div></div>'+note(bi('Les textes et PDF officiels restent à fournir par l’Agence. Aucun texte juridique de démonstration n’est présenté comme officiel.','تُوفر النصوص وملفات PDF الرسمية من طرف الوكالة. لا يُعرض أي نص تجريبي باعتباره نصًا رسميًا.'))+'<div class="legal-files" data-layout="cards" id="legal-list">'+records.map((r,i)=>'<article class="legal-file" data-kind="'+r[2]+'" data-search="'+esc(r.join(' '))+'"><div class="legal-file-top"><span class="legal-file-category">'+r[1]+'</span><span class="legal-file-index" aria-hidden="true">0'+(i+1)+'</span></div><div class="legal-file-icon" aria-hidden="true">'+IC.book+'</div><div class="legal-file-content"><h2>'+r[0]+'</h2><p>'+r[3]+'</p><dl><div><dt>'+bi('Référence','المرجع')+'</dt><dd>'+bi('À renseigner','يُستكمل')+'</dd></div><div><dt>'+bi('Date','التاريخ')+'</dt><dd>—</dd></div></dl></div><div class="legal-file-footer"><span>'+bi('Document officiel attendu','في انتظار الوثيقة الرسمية')+'</span><button type="button" disabled>'+bi('PDF à fournir','ملف PDF مطلوب')+'</button></div></article>').join('')+'</div>');
}
function searchControl(id,ph){return '<div class="library-toolbar"><label class="field-search"><span class="sr-only">'+ph+'</span><input type="search" data-list-search="'+id+'" placeholder="'+ph+'"></label><span class="content-count" data-count-for="'+id+'" role="status"></span></div>';}
function downloadBtn(kind,title){return '<button class="btn btn-secondary" type="button" data-template="'+kind+'">'+title+'</button>';}
function guidePage(isDossier=false){
 const checks=[bi('L’administration et le correspondant sont identifiés.','تم تحديد الإدارة وجهة الاتصال.'),bi('L’objet du litige et les faits sont présentés.','تم عرض موضوع النزاع والوقائع.'),bi('Les documents disponibles sont inventoriés et lisibles.','الوثائق المتوفرة مفهرسة وواضحة.'),bi('Les dates et les échanges utiles sont rassemblés.','تم جمع التواريخ والمراسلات المفيدة.')];
 return pageFrame(isDossier?'dossier':'guide',bi('Préparer une démarche, trouver les modèles et comprendre le suivi.','إعداد الإجراء والعثور على النماذج وفهم المتابعة.'),note(bi('Parcours de maquette à valider : la liste obligatoire des pièces, les délais et les canaux de transmission seront précisés par l’Agence.','مسار تجريبي للاعتماد: تحدد الوكالة الوثائق الإلزامية والآجال وقنوات الإحالة.'))+'<div class="guide-workspace"><section class="preparation"><div class="section-heading"><span class="mini-label">'+bi('Avant la transmission','قبل الإحالة')+'</span><h2>'+bi('Un dossier bien préparé.','ملف مُعد بعناية.')+'</h2><p>'+bi('Utilisez ces repères pour organiser votre dossier. Ils ne remplacent pas les exigences officielles.','استخدم هذه النقاط لتنظيم ملفك، ولا تُغني عن المتطلبات الرسمية.')+'</p></div><div class="readiness"><div class="readiness-top"><span>'+bi('Votre préparation','إعداد ملفك')+'</span><strong id="readiness-count" role="status">0 / 4</strong></div><div class="readiness-track" aria-hidden="true"><span id="readiness-fill"></span></div>'+checks.map((c,i)=>'<label class="readiness-item"><input type="checkbox" data-readiness><span>'+c+'</span></label>').join('')+'</div></section><aside class="resource-kit"><span class="mini-label">'+bi('À garder sous la main','موارد مساعدة')+'</span><h2>'+bi('Vos modèles<br>de préparation.','نماذج<br>إعداد ملفك.')+'</h2><p>'+bi('Des fichiers modifiables pour structurer les informations.','ملفات قابلة للتعديل لتنظيم المعلومات.')+'</p><div class="resource-download"><div>'+IC.folder+'<span><strong>'+bi('Fiche de transmission','بطاقة الإحالة')+'</strong><small>RTF · '+bi('Modifiable','قابل للتعديل')+'</small></span></div>'+downloadBtn('transmission',bi('Télécharger','تنزيل'))+'</div><div class="resource-download"><div>'+IC.book+'<span><strong>'+bi('Inventaire des pièces','جرد المرفقات')+'</strong><small>TXT · '+bi('Modifiable','قابل للتعديل')+'</small></span></div>'+downloadBtn('inventaire',bi('Télécharger','تنزيل'))+'</div><small class="resource-disclaimer">'+bi('Modèles de maquette à faire valider.','نماذج تجريبية تتطلب الاعتماد.')+'</small></aside></div><section class="guide-followup"><div><span class="mini-label">'+bi('Après la préparation','بعد الإعداد')+'</span><h2>'+bi('Transmettre, puis suivre.','الإحالة ثم المتابعة.')+'</h2></div><div><h3>'+bi('Où transmettre le dossier ?','أين يُحال الملف؟')+'</h3><p>'+bi('Le canal officiel sera indiqué ici après validation par l’Agence. Aucun dépôt n’est effectué depuis cette maquette.','تُحدد قناة الإحالة الرسمية هنا بعد اعتمادها. لا يتم إيداع ملفات عبر هذه الماكيت.')+'</p>'+viewLink('contact',bi('Demander une orientation','طلب التوجيه'))+'</div><div><h3>'+bi('Quels délais et quel suivi ?','ما الآجال وطرق المتابعة؟')+'</h3><p>'+bi('Les délais réglementaires restent à préciser. Le suivi des administrations habilitées est prévu via Mizan.','تُستكمل الآجال التنظيمية. وتتم متابعة الإدارات المخولة عبر ميزان.')+'</p>'+viewLink('connexion',bi('Accéder à l’espace administrations','فضاء الإدارات'))+'</div></section>');
}
function amicablePage(){
 const items=[[bi('Les conditions','الشروط'),bi('Vérifier si la démarche correspond à votre situation.','التحقق من ملاءمة الإجراء لوضعيتك.'),bi('L’Agence précisera les conditions d’éligibilité, les exclusions et les interlocuteurs compétents. Aucun critère juridique n’est présumé dans cette maquette.','تحدد الوكالة شروط القبول والاستثناءات والجهات المختصة. لا تفترض هذه الماكيت أي شرط قانوني.')],[bi('La demande','الطلب'),bi('Présenter clairement le différend.','عرض النزاع بوضوح.'),bi('Identifier les parties, expliquer les faits et préparer les pièces utiles. Le modèle proposé est un support de travail à faire valider.','تحديد الأطراف وشرح الوقائع وإعداد الوثائق المفيدة. النموذج المقترح أداة عمل للاعتماد.')],[bi('La suite du parcours','مراحل المتابعة'),bi('Recevoir une orientation de l’Agence.','الحصول على توجيه الوكالة.'),bi('Les étapes d’instruction, les modalités d’échange et les délais seront affichés après confirmation officielle.','تُعرض مراحل دراسة الطلب وطرق التبادل والآجال بعد التأكيد الرسمي.')]];
 return pageFrame('amiable',bi('Un parcours lisible pour comprendre et préparer une demande de règlement amiable.','مسار واضح لفهم طلب التسوية الودية وإعداده.'),'<div class="amicable-opening"><div><span class="mini-label">'+bi('Comprendre la démarche','فهم الإجراء')+'</span><h2>'+bi('Donner une place<br>au règlement amiable.','إتاحة المجال<br>للتسوية الودية.')+'</h2><p>'+bi('Avant de préparer votre demande, retrouvez les conditions, les informations à réunir et les étapes à confirmer auprès de l’Agence.','قبل إعداد طلبك، اطّلع على الشروط والمعلومات المطلوبة والمراحل التي ينبغي تأكيدها لدى الوكالة.')+'</p>'+downloadBtn('amiable',bi('Préparer une demande · RTF','إعداد طلب · RTF'))+'</div><figure><img src="'+PRESS_PHOTOS[2]+'" alt="'+bi('Rédaction d’un document','إعداد وثيقة')+'"><figcaption>'+bi('Photo d’illustration','صورة توضيحية')+'</figcaption></figure></div>'+note()+'<div class="amicable-chapters">'+items.map((x,i)=>'<details '+(i===0?'open':'')+'><summary><span class="chapter-index">0'+(i+1)+'</span><span><strong>'+x[0]+'</strong><small>'+x[1]+'</small></span><span class="disclosure-sign" aria-hidden="true"></span></summary><p>'+x[2]+'</p></details>').join('')+'</div><div class="quiet-cta"><span>'+bi('Vous avez besoin de préciser votre démarche ?','هل تحتاج إلى توضيح الإجراء؟')+'</span>'+viewLink('contact',bi('Contacter l’Agence','الاتصال بالوكالة'))+'</div>');
}
const courtSamples=()=>[[bi('Décision anonymisée — fiche de présentation','حكم مجهول الهوية — بطاقة عرض'),bi('Contentieux administratif','المنازعات الإدارية')],[bi('Décision anonymisée — fiche de synthèse','حكم مجهول الهوية — بطاقة تلخيص'),bi('Responsabilité de l’État','مسؤولية الدولة')],[bi('Décision anonymisée — note de lecture','حكم مجهول الهوية — مذكرة قراءة'),bi('Procédure','الإجراءات')]];
function jurisprudencePage(){
 const kinds=['administratif','responsabilite','procedure'];
 const filters=[['all',bi('Tous les thèmes','جميع المواضيع')],['administratif',bi('Administratif','إداري')],['responsabilite',bi('Responsabilité','المسؤولية')],['procedure',bi('Procédure','الإجراءات')]];
 return pageFrame('jurisprudence',bi('Rechercher et consulter les fiches de décisions anonymisées.','البحث في بطاقات الأحكام مجهولة الهوية والاطّلاع عليها.'),'<section class="case-searchboard"><div class="case-search-title"><span class="mini-label">'+bi('Explorer les décisions','استكشاف الأحكام')+'</span><h2>'+bi('Quelle décision recherchez-vous ?','ما الحكم الذي تبحث عنه؟')+'</h2></div>'+searchControl('case-list',bi('Un thème, une décision, une référence…','موضوع أو حكم أو مرجع…'))+'<div class="filter-buttons" role="group" aria-label="'+bi('Thèmes de jurisprudence','مواضيع الاجتهاد القضائي')+'">'+filters.map((r,i)=>'<button type="button" data-filter="'+r[0]+'" data-target="case-list" aria-pressed="'+(i===0)+'">'+r[1]+'</button>').join('')+'</div></section>'+note(bi('Fiches d’exemple sans décision réelle ni référence inventée. Les décisions officielles anonymisées restent à fournir.','بطاقات تجريبية دون أحكام حقيقية أو مراجع مختلقة. تُوفر الأحكام الرسمية مجهولة الهوية لاحقًا.'))+'<div class="case-workspace"><div class="case-results" id="case-list">'+courtSamples().map((r,i)=>'<article class="case-result" data-kind="'+kinds[i]+'" data-search="'+esc(r.join(' '))+'"><div class="case-result-top"><span class="case-topic">'+r[1]+'</span><span class="case-example">'+bi('Fiche d’exemple','بطاقة تجريبية')+'</span></div><div class="case-result-main"><div><h2>'+r[1]+'</h2><p>'+r[0]+'</p></div>'+viewLink('decision/'+i,bi('Lire la décision','قراءة الحكم'),'case-read')+'</div><div class="case-reference"><span>'+bi('Juridiction à renseigner','تُستكمل المحكمة')+'</span><span>'+bi('Référence à renseigner','يُستكمل المرجع')+'</span></div><details class="case-preview"><summary>'+bi('Aperçu de la fiche','نظرة على البطاقة')+'</summary><p>'+bi('La fiche réunira la question examinée, la solution et la portée de la décision. Ces éléments seront renseignés à partir du texte officiel anonymisé.','تجمع البطاقة المسألة المعروضة والحل ونطاق الحكم. تُستكمل هذه العناصر اعتمادًا على النص الرسمي مجهول الهوية.')+'</p></details></article>').join('')+'</div><aside class="case-reading"><span class="mini-label">'+bi('Bien lire une décision','قراءة الحكم')+'</span><h2>'+bi('Trois repères<br>pour comprendre.','ثلاث نقاط<br>لفهم الحكم.')+'</h2>'+[[bi('Les références','المراجع'),bi('Identifier la juridiction, la date et le document.','تحديد المحكمة والتاريخ والوثيقة.')],[bi('La question examinée','المسألة المعروضة'),bi('Comprendre le point traité par la décision.','فهم المسألة التي يتناولها الحكم.')],[bi('La solution et sa portée','الحل ونطاقه'),bi('Lire la synthèse validée à partir du texte officiel.','قراءة الملخص المعتمد من النص الرسمي.')]].map((r,i)=>'<div class="case-reading-item"><span>0'+(i+1)+'</span><div><h3>'+r[0]+'</h3><p>'+r[1]+'</p></div></div>').join('')+'<div class="case-privacy">'+bi('Les décisions publiées doivent être anonymisées et validées.','يجب أن تكون الأحكام المنشورة مجهولة الهوية ومعتمدة.')+'</div></aside></div>');
}
function decisionPage(i){const data=courtSamples()[i];if(!data)return notFound();return pageFrame('jurisprudence',data[0],note()+'<div class="detail-layout"><article class="page-prose"><h2>'+data[1]+'</h2>'+[['Identification','التعريف'],['Question examinée','المسألة المعروضة'],['Solution et portée','الحل ونطاقه']].map(t=>'<h3>'+bi(...t)+'</h3><p>'+bi('Contenu à renseigner à partir du texte officiel anonymisé. Aucun nom, numéro de dossier réel ou donnée personnelle n’est utilisé dans cet exemple.','يُستكمل المحتوى اعتمادًا على النص الرسمي مجهول الهوية. لا يتضمن هذا المثال أسماء أو أرقام ملفات حقيقية أو بيانات شخصية.')+'</p>').join('')+viewLink('jurisprudence',bi('Retour aux décisions','العودة إلى الأحكام'))+'</article><aside class="detail-side"><h3>'+bi('Informations','المعلومات')+'</h3><dl><dt>'+bi('Juridiction','المحكمة')+'</dt><dd>'+bi('À renseigner','تُستكمل')+'</dd><dt>'+bi('Date et référence','التاريخ والمرجع')+'</dt><dd>—</dd></dl><p class="page-gap"><span class="unavailable">'+bi('PDF officiel à fournir','ملف PDF رسمي مطلوب')+'</span></p></aside></div>');}
function publicationsPage(){
 const labels=[bi('Rapports','تقارير'),bi('Statistiques','إحصائيات'),bi('Jurisprudence','اجتهاد قضائي'),bi('Guides','أدلة')];
 return pageFrame('publications',bi('Les rapports, données et ressources pour mieux comprendre l’action de l’Agence.','تقارير وبيانات وموارد لفهم عمل الوكالة.'),'<div class="publication-heading"><div><span class="mini-label">'+bi('La collection de l’Agence','إصدارات الوكالة')+'</span><h2>'+bi('Des ressources<br>à consulter et à conserver.','موارد للاطّلاع<br>والاحتفاظ.')+'</h2></div><p>'+bi('Une présentation par type de document, avec une fiche dédiée et un accès prévu aux versions officielles.','عرض حسب نوع الوثيقة، مع بطاقة مستقلة ووصول مرتقب إلى النسخ الرسمية.')+'</p></div>'+note()+ '<div class="publication-controls">'+searchControl('publication-list',bi('Rechercher une publication','البحث عن منشور'))+'<div class="filter-buttons" role="group" aria-label="'+bi('Type de publication','نوع المنشور')+'">'+[['all',bi('Tout','الكل')],['rapport',labels[0]],['statistiques',labels[1]],['guide',labels[3]],['jurisprudence',labels[2]],['etudes',bi('Études','دراسات')]].map((r,i)=>'<button type="button" data-filter="'+r[0]+'" data-target="publication-list" aria-pressed="'+(i===0)+'">'+r[1]+'</button>').join('')+'</div></div><div class="publication-gallery" id="publication-list">'+T[lang].pubs.map((p,i)=>'<article class="publication-object" data-kind="'+['rapport','statistiques','jurisprudence','guide'][i]+'" data-search="'+esc(p.join(' '))+'"><a class="publication-stage tone-'+i+'" href="#/publication/'+i+'" aria-label="'+esc(p[1])+'"><span class="publication-category">'+labels[i]+'</span><img src="'+COVERS[lang][i]+'" alt="'+esc(p[1])+'" loading="lazy"><span class="publication-open" aria-hidden="true">'+AR+'</span></a><div class="publication-caption"><span class="file-chip">'+bi('DOCUMENT À FOURNIR','وثيقة مطلوبة')+'</span><h2>'+p[1]+'</h2><p>'+p[3]+'</p>'+viewLink('publication/'+i,bi('Voir la publication','عرض المنشور'))+'</div></article>').join('')+'<article class="publication-object studies-object" data-kind="etudes" data-search="'+bi('Études analyses','دراسات تحليلات')+'"><div class="studies-art" aria-hidden="true">'+IC.book+'</div><div class="publication-caption"><span class="mini-label">'+bi('Études','دراسات')+'</span><h2>'+bi('Études et analyses','الدراسات والتحليلات')+'</h2><p>'+bi('Les études validées seront réunies ici dès leur mise à disposition par l’Agence.','تُجمع الدراسات المعتمدة هنا بعد توفيرها من الوكالة.')+'</p><span class="unavailable">'+bi('Contenus à compléter','محتوى يُستكمل')+'</span></div></article></div>');
}
function publicationPage(i){const p=T[lang].pubs[i];if(!p)return notFound();return pageFrame('publications',p[1],'<div class="detail-layout"><article class="page-prose"><h2>'+p[1]+'</h2><p>'+p[3]+'</p>'+note(bi('La couverture et la fiche sont des éléments de maquette. Le document officiel doit être fourni avant d’activer le téléchargement PDF.','الغلاف والبطاقة من عناصر الماكيت. يجب توفير الوثيقة الرسمية قبل تفعيل تنزيل PDF.'))+'<p><span class="unavailable">'+bi('PDF officiel à fournir','ملف PDF رسمي مطلوب')+'</span></p>'+viewLink('publications',bi('Toutes les publications','جميع المنشورات'))+'</article><aside class="detail-side"><img src="'+COVERS[lang][i]+'" alt="'+esc(p[1])+'" style="display:block;width:160px;height:auto;margin:auto"><dl class="page-gap"><dt>'+bi('Type','النوع')+'</dt><dd>'+p[0]+'</dd><dt>'+bi('Statut','الحالة')+'</dt><dd>'+bi('Contenu à valider','محتوى للاعتماد')+'</dd></dl></aside></div>');}
function newsListingPage(){return pageFrame('actualites',bi('Suivre les activités de l’Agence et ses communiqués.','متابعة أنشطة الوكالة وبلاغاتها.'),note(bi('Actualités de démonstration et photos d’illustration. Les contenus officiels seront fournis par l’Agence.','أخبار تجريبية وصور توضيحية. توفر الوكالة المحتوى الرسمي.'))+'<div class="library-toolbar"><div class="filter-buttons" role="group" aria-label="'+bi('Type d’actualité','نوع الخبر')+'">'+['all','news','com'].map(k=>'<button type="button" data-filter="'+k+'" data-target="news-list" aria-pressed="'+(k==='all')+'">'+T[lang].secs[k]+'</button>').join('')+'</div><label class="field-search"><span class="sr-only">'+bi('Rechercher une actualité','البحث عن خبر')+'</span><input type="search" data-list-search="news-list" placeholder="'+bi('Rechercher une actualité','البحث عن خبر')+'"></label></div><p class="content-count" data-count-for="news-list" role="status"></p><div class="news-page-grid" id="news-list">'+T[lang].news.map((n,i)=>'<article class="news-page-card" data-kind="'+n[0]+'" data-search="'+esc(n[1]+' '+n[2])+'"><img src="'+PRESS_PHOTOS[i]+'" alt="'+bi('Photo d’illustration','صورة توضيحية')+'" loading="lazy"><div class="panel-content"><div class="record-meta">'+T[lang].types[n[0]]+' · '+n[3][0]+' '+T[lang].months[n[3][1]]+' 2026</div><h2>'+n[1]+'</h2>'+viewLink('actualite/'+i,T[lang].readMore)+'</div></article>').join('')+'</div>');}
function newsDetail(i){const n=T[lang].news[i];if(!n)return notFound();return pageFrame('actualites',n[1],'<div class="detail-layout"><article><img class="detail-image" src="'+PRESS_PHOTOS[i]+'" alt="'+bi('Photo d’illustration','صورة توضيحية')+'"><p class="image-credit">'+bi('Photo d’illustration · Unsplash','صورة توضيحية · Unsplash')+'</p><div class="page-prose">'+note(bi('Contenu de démonstration : ce texte ne constitue pas une actualité officielle de l’Agence.','محتوى تجريبي: لا يمثل هذا النص خبرًا رسميًا صادرًا عن الوكالة.'))+'<h2>'+n[1]+'</h2><p>'+n[2]+'</p><p>'+bi('Le texte complet, les documents associés et les photographies de l’événement seront ajoutés après validation éditoriale.','يُضاف النص الكامل والوثائق المرفقة وصور النشاط بعد الاعتماد التحريري.')+'</p>'+viewLink('actualites',bi('Retour aux actualités','العودة إلى الأخبار'))+'</div></article><aside class="detail-side"><dl><dt>'+bi('Rubrique','القسم')+'</dt><dd>'+T[lang].types[n[0]]+'</dd><dt>'+bi('Date de démonstration','تاريخ تجريبي')+'</dt><dd>'+n[3][0]+' '+T[lang].months[n[3][1]]+' 2026</dd></dl><p class="page-gap">'+viewLink('contact',routeLabel('contact'))+'</p></aside></div>');}
function faqMarkup(){const qs=[[bi('À qui s’adresse ce site ?','لمن يُوجّه هذا الموقع؟'),bi('Aux administrations publiques, magistrats, avocats, citoyens, médias et chercheurs.','للإدارات العمومية والقضاة والمحامين والمواطنين ووسائل الإعلام والباحثين.')],[bi('Comment préparer une transmission ?','كيف أُعد ملف الإحالة؟'),bi('Consultez le guide des administrations. Les pièces et modalités officielles devront être confirmées par l’Agence.','راجِع دليل الإدارات. ويجب تأكيد الوثائق وطرق الإحالة الرسمية لدى الوكالة.')],[bi('Qui peut accéder à Mizan ?','من يمكنه الولوج إلى ميزان؟'),bi('L’espace est réservé aux administrations habilitées. Cette maquette présente l’écran de connexion ; elle n’accorde aucun accès réel.','الفضاء مخصص للإدارات المخولة. تعرض هذه الماكيت شاشة الدخول ولا تمنح وصولًا حقيقيًا.')],[bi('Les décisions sont-elles anonymisées ?','هل الأحكام مجهولة الهوية؟'),bi('Le site est prévu pour publier des décisions anonymisées après validation. Les fiches actuelles sont des exemples de présentation.','صُمم الموقع لنشر أحكام مجهولة الهوية بعد اعتمادها. البطاقات الحالية أمثلة للعرض.')]];return '<section class="faq page-gap"><h2>'+bi('Questions fréquentes','الأسئلة الشائعة')+'</h2>'+qs.map(q=>'<details><summary>'+q[0]+'</summary><p>'+q[1]+'</p></details>').join('')+'</section>';}
function contactPage(){return pageFrame('contact',bi('Poser une question ou retrouver les coordonnées de l’Agence.','طرح سؤال أو الاطّلاع على بيانات الاتصال بالوكالة.'),'<div class="contact-grid"><section><h2>'+bi('Écrire à l’Agence','مراسلة الوكالة')+'</h2>'+note(bi('Formulaire de maquette non relié à une messagerie. Vous pouvez préparer et télécharger votre message ; aucun envoi n’est effectué.','نموذج غير مرتبط بخدمة مراسلة. يمكنك إعداد رسالتك وتنزيلها؛ لا يتم إرسالها.'))+'<form class="site-form" id="contact-form"><p class="required-note">'+bi('Tous les champs sont obligatoires, sauf mention contraire.','كل الحقول مطلوبة ما لم يُذكر خلاف ذلك.')+'</p><div class="form-row"><div><label for="contact-name">'+bi('Nom complet','الاسم الكامل')+'</label><input id="contact-name" name="name" autocomplete="name" required maxlength="120"></div><div><label for="contact-email">'+bi('Adresse électronique','البريد الإلكتروني')+'</label><input id="contact-email" name="email" type="email" autocomplete="email" required maxlength="180"></div></div><div><label for="contact-org">'+bi('Administration ou organisme','الإدارة أو الهيئة')+' <span class="optional">'+bi('(facultatif)','(اختياري)')+'</span></label><input id="contact-org" name="org" autocomplete="organization" maxlength="180"></div><div><label for="contact-subject">'+bi('Objet','الموضوع')+'</label><input id="contact-subject" name="subject" required maxlength="180"></div><div><label for="contact-message">'+bi('Message','الرسالة')+'</label><textarea id="contact-message" name="message" required maxlength="5000"></textarea></div><label class="consent"><input type="checkbox" required name="consent"><span>'+bi('J’ai compris que ce formulaire permet de préparer un message et ne le transmet pas à l’Agence.','أفهم أن هذا النموذج يُعدّ الرسالة ولا يرسلها إلى الوكالة.')+'</span></label><div class="form-actions"><button class="btn btn-green" type="submit">'+bi('Télécharger mon message','تنزيل رسالتي')+'</button></div><p class="form-status" role="status" id="contact-status"></p></form></section><aside class="contact-address"><h2>'+bi('Nous trouver','عنواننا')+'</h2><dl><dt>'+bi('Adresse','العنوان')+'</dt><dd>'+bi('Nouakchott, Mauritanie. Adresse précise à fournir par l’Agence.','نواكشوط، موريتانيا. توفر الوكالة العنوان الدقيق.')+'</dd><dt>'+bi('Téléphone','الهاتف')+'</dt><dd>'+bi('Numéro officiel à fournir','يُستكمل الرقم الرسمي')+'</dd><dt>'+bi('Courriel','البريد الإلكتروني')+'</dt><dd>'+bi('Adresse officielle à fournir','يُستكمل العنوان الرسمي')+'</dd><dt>'+bi('Horaires','أوقات العمل')+'</dt><dd>'+bi('À confirmer par l’Agence','تُؤكد من طرف الوكالة')+'</dd></dl></aside></div>'+faqMarkup());}
function loginPage(){return pageFrame('connexion',bi('Accès sécurisé à Mizan, réservé aux administrations habilitées.','دخول مؤمَّن إلى منصة ميزان، مخصص للإدارات المخولة.'),'<div class="login-layout"><section class="login-brand"><span class="label">MIZAN · SIGC-AJE</span><h2>'+bi('Vos dossiers, un accès dédié.','ملفاتكم في فضاء مخصص.')+'</h2><p>'+bi('Un point d’entrée pour le suivi des dossiers, des audiences et des échanges avec l’Agence.','نقطة دخول لمتابعة الملفات والجلسات والتبادل مع الوكالة.')+'</p></section><section class="login-form"><h2>'+bi('Connexion Administration','دخول الإدارات')+'</h2>'+note(bi('Écran de démonstration. La connexion Mizan sera activée lorsque l’URL et le système d’authentification seront fournis.','شاشة تجريبية. يُفعّل الدخول إلى ميزان بعد توفير الرابط ونظام المصادقة.'))+'<form class="site-form" id="login-form"><div><label for="login-id">'+bi('Identifiant professionnel','المعرّف المهني')+'</label><input id="login-id" name="identifier" autocomplete="username" required maxlength="180"></div><div><label for="login-password">'+bi('Mot de passe','كلمة المرور')+'</label><div class="password-field"><input id="login-password" name="password" type="password" autocomplete="current-password" required minlength="1"><button type="button" class="password-toggle" data-password-toggle aria-pressed="false">'+bi('Afficher','إظهار')+'</button></div></div><button class="btn btn-green" type="submit">'+bi('Se connecter','تسجيل الدخول')+'</button><p id="login-status" class="form-status" role="status"></p><p class="login-help">'+bi('Besoin d’un accès ou d’une assistance ?','هل تحتاج إلى حساب أو مساعدة؟')+' '+viewLink('contact',bi('Contacter l’Agence','الاتصال بالوكالة'))+'</p></form></section></div>');}
function wordPage(){return pageFrame('mot-agent',bi('La parole de l’Agent judiciaire de l’État.','كلمة الوكيل القضائي للدولة.'),note(bi('Texte de présentation à faire valider. Le nom, le portrait et le message officiel seront fournis par l’Agence.','نص للعرض يتطلب الاعتماد. توفر الوكالة الاسم والصورة والكلمة الرسمية.'))+'<article class="page-prose"><h2>'+T[lang].wTitle+'</h2><p>'+T[lang].quote+'</p><p>'+bi('Cette page est prévue pour accueillir la version intégrale de la lettre institutionnelle, sa date et sa signature.','خُصصت هذه الصفحة لعرض الكلمة المؤسسية كاملة مع تاريخها وتوقيعها.')+'</p>'+viewLink('agence',bi('Découvrir l’Agence','التعرّف إلى الوكالة'))+'</article>');}
function legalInfoPage(key){const texts={mentions:[bi('Éditeur du site','الجهة الناشرة'),bi('Agence judiciaire de l’État, Mauritanie. Le responsable de publication, les coordonnées, l’hébergeur et les mentions applicables seront complétés après validation.','الوكالة القضائية للدولة، موريتانيا. تُستكمل بيانات مسؤول النشر والاتصال والاستضافة والبيانات الواجبة بعد اعتمادها.')],confidentialite:[bi('Protection des données personnelles','حماية البيانات الشخصية'),bi('La politique définitive devra préciser le responsable du traitement, les finalités, les données collectées, la durée de conservation et les modalités d’exercice des droits. Dans cette maquette, les formulaires ne transmettent pas les données ; seul le choix de langue est mémorisé dans le navigateur.','تُحدد السياسة النهائية مسؤول المعالجة وأغراضها والبيانات المجموعة ومدة حفظها وطرق ممارسة الحقوق. لا تُرسل النماذج في هذه الماكيت البيانات؛ ويُحفظ اختيار اللغة فقط في المتصفح.')],accessibilite:[bi('Un site utilisable par tous','موقع متاح للجميع'),bi('La maquette propose une navigation au clavier, des libellés de formulaires, des textes alternatifs, une direction adaptée à chaque langue et une réduction des animations selon les préférences du système. Aucun niveau de conformité n’est revendiqué sans audit complet.','تتيح الماكيت التنقل بلوحة المفاتيح وتسميات النماذج والنصوص البديلة واتجاه العرض المناسب لكل لغة وتقليل الحركة وفق إعدادات النظام. لا يُدعى أي مستوى مطابقة دون تدقيق كامل.')]};const t=texts[key];return pageFrame(key,bi('Informations relatives au site institutionnel.','معلومات تخص الموقع المؤسسي.'),note()+'<article class="page-prose"><h2>'+t[0]+'</h2><p>'+t[1]+'</p>'+viewLink('contact',routeLabel('contact'))+'</article>');}
function identityPage(){return pageFrame('identite',bi('Références de couleurs, de typographie et de composants pour le développement.','مرجع الألوان والخطوط والمكونات الموجه للتطوير.'),'<section class="panel"><div class="identity-logo"><img src="'+$('.brand img').src+'" alt="'+bi('Logo de l’Agence','شعار الوكالة')+'"><div><h2>'+bi('Identité institutionnelle','الهوية المؤسسية')+'</h2><p>'+bi('Conserver les couleurs du logo. Le second emblème officiel sera intégré lorsqu’il sera fourni et validé.','تُحفظ ألوان الشعار. ويُضاف الشعار الرسمي الثاني بعد توفيره واعتماده.')+'</p></div></div></section><section class="page-gap"><h2>'+bi('Palette','لوحة الألوان')+'</h2><div class="token-grid">'+[['#0B3D2C',bi('Vert principal','الأخضر الرئيسي')],['#F2C230',bi('Or — accent','الذهبي — تمييز')],['#FFFFFF',bi('Blanc','الأبيض')],['#EEF5EC',bi('Fond clair','خلفية فاتحة')],['#B42318',bi('Rouge — alertes','الأحمر — تنبيهات')]].map(c=>'<div><div class="swatch" style="background:'+c[0]+'"></div><strong>'+c[1]+'</strong><code dir="ltr">'+c[0]+'</code></div>').join('')+'</div></section><div class="page-grid two page-gap"><section class="panel"><h2>'+bi('Typographie','الخطوط')+'</h2><p>Inter · Source Serif 4 · Cairo</p><p>'+bi('Corps de texte : 16 px minimum. Titres : 24–44 px. Deux graisses principales : 400 et 600/700. Les légendes, dates et métadonnées peuvent être plus petites.','النص الأساسي: 16 بكسل على الأقل. العناوين: من 24 إلى 44 بكسل. وزنان رئيسيان: عادي وعريض. قد تكون التعليقات والتواريخ والبيانات الوصفية أصغر.')+'</p></section><section class="panel"><h2>'+bi('Composants et états','المكونات وحالاتها')+'</h2><div class="form-actions"><button class="btn btn-green" type="button">'+bi('Action principale','إجراء رئيسي')+'</button><button class="btn btn-secondary" type="button">'+bi('Action secondaire','إجراء ثانوي')+'</button></div><p class="page-gap">'+bi('Rayons : 8–18 px. Cible tactile : 44 px recommandés. Icônes SVG à trait, 16–24 px. États : repos, survol, focus, désactivé.','الزوايا: من 8 إلى 18 بكسل. مساحة لمس موصى بها: 44 بكسل. أيقونات SVG خطية بحجم 16–24 بكسل. الحالات: عادية، مرور المؤشر، التركيز، التعطيل.')+'</p></section></div><section class="panel page-gap"><h2>'+bi('Mouvement et adaptation','الحركة والتكيّف')+'</h2><p>'+bi('Animations de 200 à 750 ms, sans bloquer la lecture. Respect de prefers-reduced-motion. Dispositions prévues pour le téléphone et l’ordinateur, avec des références de 390 px et 1440 px. Navigation RTL en arabe et LTR en français.','حركات من 200 إلى 750 ملي ثانية دون تعطيل القراءة، مع احترام إعداد تقليل الحركة. أحجام العرض المرجعية 390 و1440 بكسل. اتجاه من اليمين إلى اليسار للعربية ومن اليسار إلى اليمين للفرنسية.')+'</p></section>');}
function searchPage(){const q=new URLSearchParams((location.hash.split('?')[1]||'')).get('q')||'';const records=Object.keys(routeNames).filter(k=>!['recherche','mentions','confidentialite','accessibilite'].includes(k)).map(k=>({title:routeLabel(k),route:k})).concat(T[lang].news.map((n,i)=>({title:n[1],route:'actualite/'+i})),T[lang].pubs.map((p,i)=>({title:p[1],route:'publication/'+i})));const needle=q.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const results=records.filter(r=>r.title.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(needle));return pageFrame('recherche',bi('Rechercher une rubrique, une actualité ou une publication.','البحث عن قسم أو خبر أو منشور.'),'<form class="site-form" id="page-search-form"><label for="page-search">'+bi('Votre recherche','عبارة البحث')+'</label><div class="form-actions"><input id="page-search" name="q" type="search" value="'+esc(q)+'" required style="max-width:600px"><button class="btn btn-green">'+bi('Rechercher','بحث')+'</button></div></form><p class="content-count page-gap" role="status">'+results.length+' '+bi('résultat(s)','نتيجة')+'</p>'+results.map(r=>'<div class="list-record"><h2 class="record-title">'+r.title+'</h2>'+viewLink(r.route,bi('Ouvrir','فتح'))+'</div>').join('')+(results.length?'':'<p class="empty-state">'+bi('Aucun résultat. Essayez un autre mot-clé.','لا توجد نتائج. جرّب كلمة أخرى.')+'</p>'));}
function notFound(){return pageFrame('accueil',bi('Cette page n’existe pas.','هذه الصفحة غير موجودة.'),viewLink('accueil',bi('Revenir à l’accueil','العودة إلى الرئيسية'),'btn btn-green'));}
function animateSite(){
 if(reduce||!('IntersectionObserver' in window))return;
 flowObserver=flowObserver||new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('flow-visible');flowObserver.unobserve(entry.target);}}),{threshold:.08,rootMargin:'0px 0px -12px 0px'});
 $$('.footer .f-grid>div,.footer .f-cta,#site-view .legal-file,#site-view .case-result,#site-view .case-reading,#site-view .mission-chapters>article,#site-view .org-service').forEach((el,i)=>{if(flowSeen.has(el))return;flowSeen.add(el);el.classList.add('site-flow');el.style.setProperty('--flow-order',i%3);flowObserver.observe(el);});
 $$('#nav>a').forEach((el,i)=>el.style.setProperty('--nav-order',i));
}
function syncSiteLinks(){
 $('#drawerNav').insertAdjacentHTML('afterbegin','<a href="#/accueil">'+routeLabel('accueil')+'</a>');
 const admin=$('.header .actions a');admin.href='#/connexion';

 $('.ed3 .btn').href='#/mot-agent';$('#espace .btn').href='#/connexion';$('.f-cta .btn').href='#/contact';
 const legalKeys=['mentions','confidentialite','accessibilite'];$('#flegal').innerHTML=legalKeys.map(k=>'<a href="#/'+k+'">'+routeLabel(k)+'</a>').join('');
 $('#fmap').insertAdjacentHTML('beforeend','<a href="#/connexion">'+routeLabel('connexion')+'</a>');
 $$('.footer a.ltr').forEach(a=>{a.removeAttribute('href');a.textContent=bi('Courriel officiel à fournir','البريد الرسمي يُستكمل');});
 const label=$('#actualites .home-demo');if(label)label.textContent=bi('Actualités de démonstration et photos d’illustration — à remplacer par les contenus validés de l’Agence.','أخبار تجريبية وصور توضيحية — تُستبدل بمحتوى الوكالة المعتمد.');
}
function routeKey(){return (location.hash.replace(/^#\/?/,'').split('?')[0]||'accueil');}
function renderRoute(shouldFocus=true){
 if(!siteReady)return;const route=routeKey(),parts=route.split('/'),key=parts[0],i=Number(parts[1]);
 const home=$('#home-content'),view=$('#site-view');home.hidden=key!=='accueil';view.hidden=key==='accueil';
 if(key==='accueil'){document.title=T[lang].brand+' — '+routeLabel('accueil');observe();}else{
 const functions={agence:agencyPage,juridique:legalPage,guide:guidePage,dossier:()=>guidePage(true),amiable:amicablePage,jurisprudence:jurisprudencePage,decision:()=>decisionPage(i),publications:publicationsPage,publication:()=>publicationPage(i),actualites:newsListingPage,actualite:()=>newsDetail(i),contact:contactPage,connexion:loginPage,'mot-agent':wordPage,mentions:()=>legalInfoPage('mentions'),confidentialite:()=>legalInfoPage('confidentialite'),accessibilite:()=>legalInfoPage('accessibilite'),identite:identityPage,recherche:searchPage};
 view.innerHTML=(functions[key]||notFound)();enhanceInterior(key);document.title=(routeNames[key]?routeLabel(key):bi('Détail','التفاصيل'))+' — '+T[lang].brand;updateLists();
 }
 const activeKey=({actualite:'actualites',publication:'publications',decision:'jurisprudence','mot-agent':'agence',dossier:'guide'})[key]||key;
 $$('#nav a,#drawerNav a').forEach(a=>{const active=a.hash==='#/'+activeKey;a.classList.toggle('on',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#drawer').classList.remove('open');$('#menuBtn').setAttribute('aria-expanded','false');
 animateSite();
 if(shouldFocus){scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>{const heading=key==='accueil'?$('#accueil h1'):$('#page-title');if(heading){heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});}});}
}
function foldText(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function updateLists(){
 $$('[data-list-search]').forEach(input=>{const list=document.getElementById(input.dataset.listSearch);if(!list)return;const query=foldText(input.value.trim());const active=$('[data-target="'+input.dataset.listSearch+'"][aria-pressed=true]')?.dataset.filter||'all';let count=0;
 list.querySelectorAll('[data-search]').forEach(el=>{const visible=foldText(el.dataset.search).includes(query)&&(active==='all'||el.dataset.kind===active);el.hidden=!visible;if(visible)count++;});
 const output=$('[data-count-for="'+input.dataset.listSearch+'"]');if(output)output.textContent=count+' '+bi('résultat(s)','نتيجة');
 let empty=list.querySelector('.empty-state');if(!count&&!empty){empty=document.createElement('p');empty.className='empty-state';list.append(empty);}if(empty){empty.hidden=count>0;empty.textContent=bi('Aucun résultat. Modifiez votre recherche.','لا توجد نتائج. عدّل عبارة البحث.');}
 });
}
function downloadText(filename,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function rtfText(text){return '{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\f0\\fs24 '+[...text].map(c=>{const n=c.charCodeAt(0);return c==='\n'?'\\par\n':c==='\\'?'\\\\':c==='{'?'\\{':c==='}'?'\\}':n>127?'\\u'+(n>32767?n-65536:n)+'?':c;}).join('')+'}';}
function downloadTemplate(kind){const fields=lang==='ar'?['الإدارة:','اسم المسؤول وصفته:','البريد والهاتف:','موضوع النزاع:','الأطراف:','عرض الوقائع:','التواريخ الأساسية:','قائمة الوثائق المرفقة:','التاريخ والتوقيع:']:['Administration :','Nom et qualité du responsable :','Courriel et téléphone :','Objet du litige :','Parties concernées :','Exposé des faits :','Dates principales :','Liste des pièces jointes :','Date et signature :'];const titles={transmission:bi('Fiche de transmission','بطاقة إحالة'),amiable:bi('Demande de règlement amiable','طلب تسوية ودية'),inventaire:bi('Inventaire des pièces','جرد الوثائق')};let text=bi('MODÈLE DE MAQUETTE — À VALIDER PAR L’AGENCE','نموذج تجريبي — للاعتماد من طرف الوكالة')+'\n\n'+titles[kind]+'\n\n'+(kind==='inventaire'?bi('N° | Intitulé de la pièce | Date | Nombre de pages | Observations\n\n01 |                     |      |                 |\n02 |                     |      |                 |','الرقم | عنوان الوثيقة | التاريخ | عدد الصفحات | ملاحظات\n\n01 |                 |          |              |\n02 |                 |          |              |'):fields.join('\n\n'))+'\n\n'+bi('Ce modèle ne vaut pas saisine officielle. Vérifier les modalités auprès de l’Agence.','لا يُعدّ هذا النموذج إحالة رسمية. تُراجع طرق الإحالة لدى الوكالة.');downloadText('aje-modele-'+kind+(kind==='inventaire'?'.txt':'.rtf'),kind==='inventaire'?text:rtfText(text),kind==='inventaire'?'text/plain;charset=utf-8':'application/rtf');}
function siteInit(){
 const home=document.createElement('div');home.id='home-content';const main=$('main');while(main.firstChild)home.append(main.firstChild);main.append(home);main.id='main-content';
 const view=document.createElement('div');view.id='site-view';view.className='site-page';view.hidden=true;main.append(view);
 document.body.insertAdjacentHTML('afterbegin','<a class="skip-link" id="skip-main" href="#main-content">'+bi('Aller au contenu','انتقل إلى المحتوى')+'</a>');
 $('#actualites .wrap').insertAdjacentHTML('beforeend','<p class="home-demo"></p>');
 siteReady=true;syncSiteLinks();renderRoute(false);
 const form=$('.hsearch');form.removeAttribute('onsubmit');form.addEventListener('submit',e=>{e.preventDefault();const query=$('#q').value.trim();if(query)location.hash='/recherche?q='+encodeURIComponent(query);});
 document.addEventListener('input',e=>{if(e.target.matches('[data-list-search]'))updateLists();});
 document.addEventListener('change',e=>{if(e.target.matches('[data-readiness]')){const checked=$$('[data-readiness]:checked').length;$('#readiness-count').textContent=checked+' / 4';$('#readiness-fill').style.width=(checked*25)+'%';}});
 document.addEventListener('click',e=>{
 const layout=e.target.closest('[data-legal-layout]');if(layout){$('#legal-list').dataset.layout=layout.dataset.legalLayout;$$('[data-legal-layout]').forEach(b=>b.setAttribute('aria-pressed',b===layout));}
 const topic=e.target.closest('[data-contact-topic]');if(topic){$$('[data-contact-topic]').forEach(b=>b.setAttribute('aria-pressed',b===topic));$('#contact-subject').value=({demarche:bi('Demande d’orientation','طلب توجيه'),mizan:bi('Demande d’accès Mizan','طلب الولوج إلى ميزان'),autre:bi('Demande d’information','طلب معلومات')})[topic.dataset.contactTopic];$('#contact-subject').focus();}
 if(e.target.closest('[data-print]'))window.print();
 const filterBtn=e.target.closest('[data-filter]');if(filterBtn){$$('[data-target="'+filterBtn.dataset.target+'"]').forEach(b=>b.setAttribute('aria-pressed',b===filterBtn));updateLists();}
 const template=e.target.closest('[data-template]');if(template)downloadTemplate(template.dataset.template);
 const tabButton=e.target.closest('[data-tab]');if(tabButton){$$('[role=tab]').forEach(b=>{const active=b===tabButton;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;document.getElementById(b.dataset.tab).hidden=!active;});}
 if(e.target.closest('[data-password-toggle]')){const p=$('#login-password'),btn=e.target.closest('button');const show=p.type==='password';p.type=show?'text':'password';btn.setAttribute('aria-pressed',show);btn.textContent=show?bi('Masquer','إخفاء'):bi('Afficher','إظهار');}
 if(e.target.closest('#skip-main')){e.preventDefault();const m=$('#main-content');m.setAttribute('tabindex','-1');m.focus();}
 });
 document.addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]'))return;const tabs=$$('[role=tab]');let i=tabs.indexOf(e.target);if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else if(['ArrowRight','ArrowLeft'].includes(e.key))i=(i+(e.key==='ArrowRight'?1:-1)*(lang==='ar'?-1:1)+tabs.length)%tabs.length;else return;e.preventDefault();tabs[i].click();tabs[i].focus();});
 document.addEventListener('submit',e=>{
 if(e.target.id==='login-form'){e.preventDefault();$('#login-status').textContent=bi('Connexion non activée dans la maquette. Aucun identifiant ni mot de passe n’a été transmis ou enregistré.','الدخول غير مفعل في الماكيت. لم يُرسل أو يُحفظ أي معرّف أو كلمة مرور.');$('#login-password').value='';}
 if(e.target.id==='contact-form'){e.preventDefault();const data=new FormData(e.target);const text=[bi('Brouillon de message — aucun envoi effectué','مسودة رسالة — لم يتم الإرسال'),'','Nom / الاسم : '+data.get('name'),'Courriel / البريد : '+data.get('email'),'Administration / الإدارة : '+data.get('org'),'Objet / الموضوع : '+data.get('subject'),'',data.get('message')].join('\n');downloadText('aje-message.txt',text);$('#contact-status').textContent=bi('Votre brouillon est prêt à télécharger. Aucun message n’a été envoyé.','مسودة الرسالة جاهزة للتنزيل. لم يتم إرسال أي رسالة.');}
 if(e.target.id==='page-search-form'){e.preventDefault();location.hash='/recherche?q='+encodeURIComponent(new FormData(e.target).get('q'));}
 });
 addEventListener('hashchange',()=>renderRoute(true));
 $('#langBtn').addEventListener('click',()=>{$('#skip-main').textContent=bi('Aller au contenu','انتقل إلى المحتوى');});
}
